using System;using System.IO;using System.Drawing;using System.Windows.Forms;using System.Threading.Tasks;using System.Collections.Generic;
sealed partial class Companion {
 internal async Task RunNavigationChecks(){var checks=new List<string>();try{NewNote("Navigation test","# Project notes\n\nText should remain smooth when moving.");SetView("Notes");Compact(true);allNotesTab.PerformClick();if(split.Panel1Collapsed||!split.Panel2Collapsed)throw new Exception("Compact All notes did not open list");checks.Add("Standalone compact All notes opens the list");currentNoteTab.PerformClick();if(!split.Panel1Collapsed||split.Panel2Collapsed)throw new Exception("Current note did not open page");checks.Add("Standalone compact Current note returns to page");Compact(false);ClientSize=new Size(1000,750);allNotesTab.PerformClick();if(split.Panel1Collapsed||split.Panel2Collapsed)throw new Exception("Wide list and page should coexist");checks.Add("Full notebook All notes shows the list beside the current page");currentNoteTab.PerformClick();noteMode.SelectedItem="Plain text";UpdatePageView();store.Pref.Opacity=65;ApplyFloating();await Task.Delay(250);formattedPage.Refresh();await Task.Delay(80);var before=SolidText.BoundsFor(formattedPage);int paints=SolidText.PaintsFor(formattedPage);IntPtr surface=noteBackground.Plate.Handle;BorderlessWindow.SendMessage(Handle,0x231,IntPtr.Zero,IntPtr.Zero);for(int n=0;n<25;n++){Location=new Point(Left+2,Top+1);Application.DoEvents();}BorderlessWindow.SendMessage(Handle,0x232,IntPtr.Zero,IntPtr.Zero);var after=SolidText.BoundsFor(formattedPage);if(!before.HasValue||!after.HasValue||after.Value.X!=before.Value.X+50||after.Value.Y!=before.Value.Y+25)throw new Exception("Transparent text surface did not follow movement");if(SolidText.PaintsFor(formattedPage)!=paints)throw new Exception("Movement repainted the transparent text surface");if(noteBackground.Plate.Bounds!=Bounds)throw new Exception("Background plate did not follow movement");ApplyFloating();if(noteBackground.Plate.Handle!=surface||SolidText.PaintsFor(formattedPage)!=paints)throw new Exception("Unchanged appearance recreated or repainted transparent surfaces");checks.Add("Transparent movement reuses text and background surfaces without text repaints");await RunOctoberChecks(checks);store.Pref.Opacity=100;ApplyFloating();if(noteBackground.Plate.Visible||TransparencyKey!=Color.Empty)throw new Exception("Opaque mode retained transparency helpers");checks.Add("Opaque window disables transparency surfaces");Store.Atomic(Path.Combine(Program.Test,"navigation-result.json"),Store.Json.Serialize(new{ok=true,checks=checks}));}catch(Exception error){Store.Atomic(Path.Combine(Program.Test,"navigation-result.json"),Store.Json.Serialize(new{ok=false,error=error.ToString(),checks=checks}));}exiting=true;Close();}
}
